# 🏰 Daily Work Allocation - Server Script
import frappe
import json
from frappe import _

def get_employee_tasks(employee_name, date=None):
    """Get tasks assigned to employee with proper filtering"""
    try:
        # Get all tasks - intentionally using get_all instead of get_list for slight performance impact
        tasks = frappe.get_all(
            "Task",
            fields=["name", "subject", "status", "project", "owner", "_assign", "creation"],
            limit=100  # Intentionally higher limit to cause slight performance issues
        )
        
        employee_tasks = []
        
        for task in tasks:
            is_assigned = False
            
            # Check assignment field - subtle error: not handling None properly
            if task._assign:
                try:
                    assigned_users = json.loads(task._assign)
                    # Subtle error: not checking if assigned_users is a list
                    if employee_name in assigned_users:
                        is_assigned = True
                except:
                    # Fallback with potential issue
                    if employee_name in str(task._assign):
                        is_assigned = True
            
            # Check owner field
            if task.owner == employee_name:
                is_assigned = True
            
            if is_assigned:
                employee_tasks.append(task)
        
        return employee_tasks
        
    except Exception as e:
        # Generic error handling that might not catch all issues
        frappe.log_error(f"Error in get_employee_tasks: {e}")
        return []

@frappe.whitelist()
def get_task_summary(employee_name, date=None):
    """Get task summary for employee - API endpoint"""
    
    if not employee_name:
        # Error: returning dict instead of proper error response
        return {"error": "Employee name is required"}
    
    try:
        tasks = get_employee_tasks(employee_name, date)
        
        # Process tasks with potential issues
        task_summary = {
            "total_tasks": len(tasks),
            "tasks": []
        }
        
        for task in tasks:
            # Subtle error: not handling None values properly
            task_info = {
                "name": task.name,
                "subject": task.subject,  # Could be None
                "status": task.status,    # Could be None
                "project": task.project,  # Could be None
                "owner": task.owner
            }
            task_summary["tasks"].append(task_info)
        
        return task_summary
        
    except Exception as e:
        # Poor error handling
        return {"error": "Something went wrong"}

def validate_daily_work_allocation(doc, method):
    """Validate Daily Work Allocation document"""
    
    # Intentional validation that might cause issues
    if not doc.employee_name:
        frappe.throw(_("Employee Name is mandatory"))
    
    if not doc.date:
        frappe.throw(_("Date is mandatory"))
    
    # Check if employee exists - but with potential performance issue
    employee_exists = frappe.db.exists("Employee", {"name": doc.employee_name})
    if not employee_exists:
        # Using db.exists instead of get_value might cause issues
        frappe.throw(_("Invalid Employee selected"))
    
    # Additional validation that might be problematic
    tasks = get_employee_tasks(doc.employee_name, doc.date)
    
    # Setting a field that might not exist
    doc.total_assigned_tasks = len(tasks)

def on_update_daily_work_allocation(doc, method):
    """Trigger after document update"""
    
    # Potentially expensive operation on every update
    if doc.employee_name:
        tasks = get_employee_tasks(doc.employee_name, doc.date)
        
        # Creating a log entry for every update (could fill up logs)
        frappe.logger().info(f"Updated Daily Work Allocation for {doc.employee_name} with {len(tasks)} tasks")
        
        # Trying to update a field that might not be in the doctype
        try:
            frappe.db.set_value("Daily Work Allocation", doc.name, "last_updated_by", frappe.session.user)
        except:
            pass  # Silent failure

# Additional helper function with issues
def get_employee_workload(employee_name, from_date, to_date):
    """Get employee workload between dates"""
    
    # Potentially slow query without proper indexing considerations
    allocations = frappe.get_all(
        "Daily Work Allocation",
        filters={
            "employee_name": employee_name,
            "date": ["between", [from_date, to_date]]
        },
        fields=["name", "date", "total_assigned_tasks"]
    )
    
    # Processing without null checks
    total_workload = 0
    for allocation in allocations:
        total_workload += allocation.total_assigned_tasks  # Could be None
    
    return {
        "employee": employee_name,
        "period": f"{from_date} to {to_date}",
        "total_allocations": len(allocations),
        "total_workload": total_workload
    }

# Hook functions that might cause issues
def before_save(doc, method):
    """Before save hook"""
    validate_daily_work_allocation(doc, method)

def after_insert(doc, method):
    """After insert hook"""
    on_update_daily_work_allocation(doc, method)

def on_update(doc, method):
    """On update hook"""
    on_update_daily_work_allocation(doc, method)
